c1:
PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?titre
WHERE {
  ?f a cine:Film ;
     cine:annee ?a ;
     cine:titre ?titre .
  FILTER (?a < 2000 && lang(?titre) = "fr")
}
ORDER BY ?a

c2:
PREFIX cine: <http://example.org/cinema/vocab#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ex:   <http://example.org/cinema/>
SELECT DISTINCT ?nom
WHERE {
  ?f cine:realisePar ex:besson .
  ?r cine:film ?f ;
     cine:acteur ?a .
  ?a foaf:name ?nom .
}

c3:
PREFIX cine: <http://example.org/cinema/vocab#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?nom (COUNT(?p) AS ?n)
WHERE {
  ?p a cine:Projection ;
     cine:cinema ?c .
  ?c rdfs:label ?nom .
}
GROUP BY ?nom

PREFIX cine: <http://example.org/cinema/vocab#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?nom (___ AS ?n)
WHERE {
  ?p a cine:Projection ;
     cine:cinema ?c .
  ?c rdfs:label ?nom .
}
GROUP BY ___

