c5:
PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?titre
WHERE {
  ?f a cine:Film ;
     cine:titre ?titre .
  FILTER (lang(?titre) = "fr")
  FILTER NOT EXISTS {
    ?f cine:titre ?autre .
    FILTER (lang(?autre) = "en")
  }
}

c6:
PREFIX cine: <http://example.org/cinema/vocab#>
SELECT ?ville (COUNT(DISTINCT ?f) AS ?films)
WHERE {
  ?p cine:cinema ?c ;
     cine:film ?f .
  ?c cine:ville ?ville .
}
GROUP BY ?ville

c7:
PREFIX cine: <http://example.org/cinema/vocab#>
PREFIX ex:   <http://example.org/cinema/>
ASK {
  ?r cine:acteur ex:reno ;
     cine:film ?f .
  ?f cine:realisePar ex:besson .
}

c8:
PREFIX cine: <http://example.org/cinema/vocab#>
CONSTRUCT { ?f cine:distribution ?a }
WHERE {
  ?r cine:film ?f ;
     cine:acteur ?a .
}
